5	# Choice
6	
7	> A Choice is a System One question type for selecting one option from a defined set. The answer includes the selected option, a probability for each option, and confidence.
8	
9	export function TypesafeExample({example, display, title}) {
10	  const keyStrUriSafe = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+-$";
11	  function compressToEncodedURIComponent(input) {
12	    if (input == null) return "";
13	    return _compress(input, 6, function (a) {
14	      return keyStrUriSafe.charAt(a);
15	    });
16	  }
17	  function _compress(uncompressed, bitsPerChar, getCharFromInt) {
18	    if (uncompressed == null) return "";
19	    var i, value, context_dictionary = {}, context_dictionaryToCreate = {}, context_c = "", context_wc = "", context_w = "", context_enlargeIn = 2, context_dictSize = 3, context_numBits = 2, context_data = [], context_data_val = 0, context_data_position = 0, ii;
20	    for (ii = 0; ii < uncompressed.length; ii += 1) {
21	      context_c = uncompressed.charAt(ii);
22	      if (!Object.prototype.hasOwnProperty.call(context_dictionary, context_c)) {
23	        context_dictionary[context_c] = context_dictSize++;
24	        context_dictionaryToCreate[context_c] = true;
25	      }
26	      context_wc = context_w + context_c;
27	      if (Object.prototype.hasOwnProperty.call(context_dictionary, context_wc)) {
28	        context_w = context_wc;
29	      } else {
30	        if (Object.prototype.hasOwnProperty.call(context_dictionaryToCreate, context_w)) {
31	          if (context_w.charCodeAt(0) < 256) {
32	            for (i = 0; i < context_numBits; i++) {
33	              context_data_val = context_data_val << 1;
34	              if (context_data_position == bitsPerChar - 1) {
35	                context_data_position = 0;
36	                context_data.push(getCharFromInt(context_data_val));
37	                context_data_val = 0;
38	              } else {
39	                context_data_position++;
40	              }
41	            }
42	            value = context_w.charCodeAt(0);
43	            for (i = 0; i < 8; i++) {
44	              context_data_val = context_data_val << 1 | value & 1;
45	              if (context_data_position == bitsPerChar - 1) {
46	                context_data_position = 0;
47	                context_data.push(getCharFromInt(context_data_val));
48	                context_data_val = 0;
49	              } else {
50	                context_data_position++;
51	              }
52	              value = value >> 1;
53	            }
54	          } else {
55	            value = 1;
56	            for (i = 0; i < context_numBits; i++) {
57	              context_data_val = context_data_val << 1 | value;
58	              if (context_data_position == bitsPerChar - 1) {
59	                context_data_position = 0;
60	                context_data.push(getCharFromInt(context_data_val));
61	                context_data_val = 0;
62	              } else {
63	                context_data_position++;
64	              }
65	              value = 0;
66	            }
67	            value = context_w.charCodeAt(0);
68	            for (i = 0; i < 16; i++) {
69	              context_data_val = context_data_val << 1 | value & 1;
70	              if (context_data_position == bitsPerChar - 1) {
71	                context_data_position = 0;
72	                context_data.push(getCharFromInt(context_data_val));
73	                context_data_val = 0;
74	              } else {
75	                context_data_position++;
76	              }
77	              value = value >> 1;
78	            }
79	          }
80	          context_enlargeIn--;
81	          if (context_enlargeIn == 0) {
82	            context_enlargeIn = Math.pow(2, context_numBits);
83	            context_numBits++;
84	          }
85	          delete context_dictionaryToCreate[context_w];
86	        } else {
87	          value = context_dictionary[context_w];
88	          for (i = 0; i < context_numBits; i++) {
89	            context_data_val = context_data_val << 1 | value & 1;
90	            if (context_data_position == bitsPerChar - 1) {
91	              context_data_position = 0;
92	              context_data.push(getCharFromInt(context_data_val));
93	              context_data_val = 0;
94	            } else {
95	              context_data_position++;
96	            }
97	            value = value >> 1;
98	          }
99	        }
100	        context_enlargeIn--;
101	        if (context_enlargeIn == 0) {
102	          context_enlargeIn = Math.pow(2, context_numBits);
103	          context_numBits++;
104	        }
105	        context_dictionary[context_wc] = context_dictSize++;
106	        context_w = String(context_c);
107	      }
108	    }
109	    if (context_w !== "") {
110	      if (Object.prototype.hasOwnProperty.call(context_dictionaryToCreate, context_w)) {
111	        if (context_w.charCodeAt(0) < 256) {
112	          for (i = 0; i < context_numBits; i++) {
113	            context_data_val = context_data_val << 1;
114	            if (context_data_position == bitsPerChar - 1) {
115	              context_data_position = 0;
116	              context_data.push(getCharFromInt(context_data_val));
117	              context_data_val = 0;
118	            } else {
119	              context_data_position++;
120	            }
121	          }
122	          value = context_w.charCodeAt(0);
123	          for (i = 0; i < 8; i++) {
124	            context_data_val = context_data_val << 1 | value & 1;
125	            if (context_data_position == bitsPerChar - 1) {
126	              context_data_position = 0;
127	              context_data.push(getCharFromInt(context_data_val));
128	              context_data_val = 0;
129	            } else {
130	              context_data_position++;
131	            }
132	            value = value >> 1;
133	          }
134	        } else {
135	          value = 1;
136	          for (i = 0; i < context_numBits; i++) {
137	            context_data_val = context_data_val << 1 | value;
138	            if (context_data_position == bitsPerChar - 1) {
139	              context_data_position = 0;
140	              context_data.push(getCharFromInt(context_data_val));
141	              context_data_val = 0;
142	            } else {
143	              context_data_position++;
144	            }
145	            value = 0;
146	          }
147	          value = context_w.charCodeAt(0);
148	          for (i = 0; i < 16; i++) {
149	            context_data_val = context_data_val << 1 | value & 1;
150	            if (context_data_position == bitsPerChar - 1) {
151	              context_data_position = 0;
152	              context_data.push(getCharFromInt(context_data_val));
153	              context_data_val = 0;
154	            } else {
155	              context_data_position++;
156	            }
157	            value = value >> 1;
158	          }
159	        }
160	        context_enlargeIn--;
161	        if (context_enlargeIn == 0) {
162	          context_enlargeIn = Math.pow(2, context_numBits);
163	          context_numBits++;
164	        }
165	        delete context_dictionaryToCreate[context_w];
166	      } else {
167	        value = context_dictionary[context_w];
168	        for (i = 0; i < context_numBits; i++) {
169	          context_data_val = context_data_val << 1 | value & 1;
170	          if (context_data_position == bitsPerChar - 1) {
171	            context_data_position = 0;
172	            context_data.push(getCharFromInt(context_data_val));
173	            context_data_val = 0;
174	          } else {
175	            context_data_position++;
176	          }
177	          value = value >> 1;
178	        }
179	      }
180	      context_enlargeIn--;
181	      if (context_enlargeIn == 0) {
182	        context_enlargeIn = Math.pow(2, context_numBits);
183	        context_numBits++;
184	      }
185	    }
186	    value = 2;
187	    for (i = 0; i < context_numBits; i++) {
188	      context_data_val = context_data_val << 1 | value & 1;
189	      if (context_data_position == bitsPerChar - 1) {
190	        context_data_position = 0;
191	        context_data.push(getCharFromInt(context_data_val));
192	        context_data_val = 0;
193	      } else {
194	        context_data_position++;
195	      }
196	      value = value >> 1;
197	    }
198	    while (true) {
199	      context_data_val = context_data_val << 1;
200	      if (context_data_position == bitsPerChar - 1) {
201	        context_data.push(getCharFromInt(context_data_val));
202	        break;
203	      } else context_data_position++;
204	    }
205	    return context_data.join("");
206	  }
207	  function buildHref(ex) {
208	    const documentText = ex.state === undefined ? "" : typeof ex.state === "string" ? ex.state : JSON.stringify(ex.state, null, 2);
209	    return "https://console.typesafe.ai/decode#share/" + compressToEncodedURIComponent(JSON.stringify({
210	      apiVersion: "v1",
211	      documentText,
212	      promptsText: JSON.stringify(ex.questions, null, 2),
213	      selectedModels: ex.selectedModels
214	    }));
215	  }
216	  const displayedExample = display === "questions" ? example.questions : example.state === undefined ? {
217	    questions: example.questions
218	  } : {
219	    state: example.state,
220	    questions: example.questions
221	  };
222	  const code = JSON.stringify(displayedExample, null, 2);
223	  const href = buildHref(example);
224	  return <div style={{
225	    margin: "1.25rem 0"
226	  }}>
227	      <CodeBlock language="json" filename={title ?? "request"}>
228	        {code}
229	      </CodeBlock>
230	      <div className="pb-8">
231	        <a href={href} target="_blank" rel="noreferrer" className="text-primary">
232	          Try it in the Playground →
233	        </a>
234	      </div>
235	    </div>;
236	}
237	
238	Use a Choice when the answer is one of a fixed set of options. For example, which team handles a ticket, which category a product belongs to, or which language a code snippet is written in. If the answer is a position on a spectrum, use a [Score](/primitives/score). If it's a yes or no, use a [Noul](/primitives/noul). [Choose a question type](/primitives#choose-a-question-type) compares all three.
239	
240	A Choice answer is the selected option in `choice`. The model also returns a probability for every option in `probabilities`, and a `confidence` value for the selected option.
241	
242	Example questions:
243	
244	```
245	"What programming language is this code written in"
246	  → options: python, javascript, typescript, go, rust, other
247	
248	"What type of meeting is this based on the title and description"
249	  → options: standup, planning, retrospective, one on one, brainstorm, none of the above
250	
251	"Which product category does this item belong to"
252	  → options: electronics, clothing, home garden, food and beverage
253	```
254	
255	## Request structure
256	
257	The POST request body to the [TypeSafe API](/api) has a specific structure. The top level has three fields: `state`, the content to evaluate; `model`; and `questions`, a map from question ids you choose to question objects. Each Choice question has the following fields:
258	
259	* `type`: Always `"choice"`.
260	* `instructions`: The question the model answers.
261	* `criteria`: The answer options, as a map. Each key is an option name and each value is a description of that option.
262	
263	Below is a request where the state is a support ticket from an online shoe store and the question is which team should handle it:
264	
265	<TypesafeExample
266	  display="request"
267	  example={{
268	state: 'My running shoes arrived in the wrong size. Can I swap them for a size 10?',
269	selectedModels: ['jev-latest'],
270	questions: {
271	  department: {
272	    type: 'choice',
273	    instructions: 'Which team should handle this?',
274	    criteria: {
275	      returns: 'Exchanges, wrong or damaged items',
276	      shipping: 'Delivery status, delays, lost packages',
277	      billing: 'Charges, invoices, payment problems',
278	    },
279	  },
280	},
281	}}
282	/>
283	
284	You choose the question id, `department` in this case. The answer is returned under the same id. The model never sees the question id. The option names and their descriptions are both sent to the model, so write descriptions that separate the options from each other.
285	
286	Our [client SDKs](/sdk) provide typed questions. In Python, the same question is a `Choice`:
287	
288	```python theme={null}
289	from typesafe_sdk import Choice, TypeSafeClient
290	
291	with TypeSafeClient() as client:
292	    response = client.system_one(
293	        state="My running shoes arrived in the wrong size. Can I swap them for a size 10?",
294	        questions={
295	            "department": Choice(
296	                instructions="Which team should handle this?",
297	                criteria={
298	                    "returns": "Exchanges, wrong or damaged items",
299	                    "shipping": "Delivery status, delays, lost packages",
300	                    "billing": "Charges, invoices, payment problems",
301	                },
302	            ),
303	        },
304	    )
305	
306	    print(response.answers["department"].choice)
307	```
308	
309	Use the `system_one` method or the `https://api.typesafe.ai/v1/systemone` endpoint to call a System One model. The `model` field selects which model handles the request. [How to build with TypeSafe](/concepts/how-to-build-with-system-one) covers where in your code to call it.
310	
311	Use one of our [client SDKs](/sdk) or call the [HTTP API](/api) directly. If a coding agent is writing the integration for you, install the [TypeSafe agent skill](/agent-skill#installation) first so it knows the request and response shapes.
312	
313	<Note>
314	  `instructions` and each entry in `criteria` can be a string, an object, or an array. Start with a string. Use an object when a description needs several kinds of guidance, such as what an option covers, what it doesn't cover, and some examples. See [Structured instructions and criteria](#structured-instructions-and-criteria) below and the [API reference](/api#param-instructions-1).
315	</Note>
316	
317	## Response structure
318	
319	The response has one entry in `answers` per question, under the ids from the request. This is the response to the example request above:
320	
321	```json theme={null}
322	{
323	  "model": "jev-1.13.0",
324	  "answers": {
325	    "department": {
326	      "type": "choice",
327	      "choice": "returns",
328	      "confidence": 1.0,
329	      "probabilities": {
330	        "shipping": 0.0,
331	        "returns": 1.0,
332	        "billing": 0.0
333	      }
334	    }
335	  },
336	  "usage": {
337	    "input_tokens": 328,
338	    "output_tokens": 34
339	  }
340	}
341	```
342	
343	Besides `type`, each Choice answer has three values:
344	
345	* `choice`: The option with the highest probability.
346	* `probabilities`: The full probability distribution across every option. The sum of all values is 1.
347	* [`confidence`](/confidence): A number from 0 to 1 computed from how `probabilities` is spread. A flat shape, with probability spread across several options, means low confidence. A single peak on one option means high confidence.
348	
349	This ticket is an easy one, so all of the probability is on `returns` and confidence is 1.0. A ticket that mentions a wrong size and a missing refund would split probability between `returns` and `billing`, and confidence would drop.
350	
351	## Good practice: ask more than one question per call
352	
353	Ask every Choice question your code might need in a single request rather than one request per question. Questions are evaluated in parallel. Adding questions barely changes the response time, and the code can ignore answers it doesn't need. Extra questions still cost tokens. [Ask multiple questions together](/primitives#ask-multiple-questions-together) explains this in full; the next section shows five Choice questions in one call.
354	
355	The same logic applies to the options inside a single Choice question. A Choice question accepts up to 255 options, and adding options costs a few tokens each, so give the model the full list of teams, categories, or products rather than a shortlist. Add an `other` or `none of the above` option when the list might not cover every input, so the model can say none of the others fit.
356	
357	To classify documents through a deep hierarchy or large taxonomy, chain Choice questions level by level. The [Hierarchical Classification cookbook](/cookbooks/hierarchical_classification) shows how to run a beam search over Choice probabilities, keeping the best `K` candidate paths at each level instead of committing to a single greedy path.
358	
359	## A more complex example
360	
361	The basic example above routes a ticket to a team. A bigger support system might also need the return reason, the delivery problem, what the customer wants, and the customer's tone.
362	
363	The request below asks five Choice questions about a ticket that is more ambiguous than the first: it involves three teams and doesn't say what the customer wants.
364	
365	<TypesafeExample
366	  display="request"
367	  example={{
368	state: 'Shoes arrived two weeks late and in the wrong size. Also I see two charges of $120 on my card. What are you going to do about this?',
369	selectedModels: ['jev-latest'],
370	questions: {
371	  department: {
372	    type: 'choice',
373	    instructions: 'Which team should handle this?',
374	    criteria: {
375	      returns: 'Exchanges, wrong or damaged items',
376	      shipping: 'Delivery status, delays, lost packages',
377	      billing: 'Charges, invoices, payment problems',
378	    },
379	  },
380	  return_reason: {
381	    type: 'choice',
382	    instructions: 'If the customer wants to return something, why?',
383	    criteria: {
384	      wrong_size: "The item doesn't fit",
385	      wrong_item: 'A different product was delivered',
386	      damaged: 'The item arrived broken or faulty',
387	      changed_mind: 'The item is fine, the customer no longer wants it',
388	      other: 'A return reason that fits none of the above',
389	    },
390	  },
391	  shipping_issue: {
392	    type: 'choice',
393	    instructions: 'If this is a shipping problem, which kind is it?',
394	    criteria: {
395	      not_delivered: 'The package never arrived',
396	      delayed: 'The package is late but still on its way',
397	      wrong_address: 'The package went to the wrong place',
398	      damaged_in_transit: 'The package arrived damaged',
399	      other: 'A shipping problem that fits none of the above',
400	    },
401	  },
402	  requested_resolution: {
403	    type: 'choice',
404	    instructions: 'What does the customer want to happen?',
405	    criteria: {
406	      exchange: 'Swap the item for a different one',
407	      refund: 'Money back',
408	      replacement: 'The same item sent again',
409	      information: 'Just an answer, no action needed',
410	    },
411	  },
412	  tone: {
413	    type: 'choice',
414	    instructions: "What is the customer's tone?",
415	    criteria: {
416	      calm: null,
417	      frustrated: null,
418	      angry: null,
419	    },
420	  },
421	},
422	}}
423	/>
424	
425	Two of these Choice questions are speculative: `return_reason` only matters if the `department` is `returns`, and `shipping_issue` only matters if it's `shipping`. The `tone` question uses `null` descriptions because the option names are clear on their own.
426	
427	The TypeSafe response:
428	
429	```json theme={null}
430	{
431	  "model": "jev-1.13.0",
432	  "answers": {
433	    "department": {
434	      "type": "choice",
435	      "choice": "returns",
436	      "confidence": 0.42,
437	      "probabilities": {
438	        "shipping": 0.04,
439	        "billing": 0.35,
440	        "returns": 0.61
441	      }
442	    },
443	    "return_reason": {
444	      "type": "choice",
445	      "choice": "wrong_size",
446	      "confidence": 1.0,
447	      "probabilities": {
448	        "other": 0.0,
449	        "wrong_size": 1.0,
450	        "changed_mind": 0.0,
451	        "damaged": 0.0,
452	        "wrong_item": 0.0
453	      }
454	    },
455	    "shipping_issue": {
456	      "type": "choice",
457	      "choice": "delayed",
458	      "confidence": 0.67,
459	      "probabilities": {
460	        "wrong_address": 0.0,
461	        "other": 0.26,
462	        "not_delivered": 0.0,
463	        "damaged_in_transit": 0.0,
464	        "delayed": 0.74
465	      }
466	    },
467	    "requested_resolution": {
468	      "type": "choice",
469	      "choice": "refund",
470	      "confidence": 0.2,
471	      "probabilities": {
472	        "replacement": 0.34,
473	        "refund": 0.4,
474	        "information": 0.02,
475	        "exchange": 0.24
476	      }
477	    },
478	    "tone": {
479	      "type": "choice",
480	      "choice": "frustrated",
481	      "confidence": 0.76,
482	      "probabilities": {
483	        "frustrated": 0.84,
484	        "angry": 0.16,
485	        "calm": 0.0
486	      }
487	    }
488	  },
489	  "usage": {
490	    "input_tokens": 589,
491	    "output_tokens": 212
492	  }
493	}
494	```
495	
496	Each question is answered on its own against the ticket:
497	
498	* The `department` answer is `returns` with a 0.61 probability, but `billing` has 0.35 because of the double charge. The ticket belongs to two teams, and the split confidence of 0.42 reflects that.
499	* The `return_reason` is `wrong_size` with a confidence of 1.0, which is expected because it says this clearly in the ticket.
500	* The `shipping_issue` answer is split between `delayed` and `other`. It's a speculative question and `department` didn't come back as shipping, so it can be ignored by the code, as shown in the example code snippet below.
501	* The `requested_resolution` answer leans to `refund` at 0.40, with `replacement` and `exchange` sharing most of the rest, and the confidence is 0.20. The double charge suggests money back, the wrong size suggests a swap, and the customer never says which they want.
502	* The `tone` answer is `frustrated` with a probability of 0.84 and a confidence of 0.76.
503	
504	The example code below reads the answers it needs, ignores the rest, and treats a low-confidence answer as a reason to ask rather than act:
505	
506	```python theme={null}
507	from typesafe_sdk import Choice, TypeSafeClient
508	
509	TRIAGE_QUESTIONS = {
510	    "department": Choice(
511	        instructions="Which team should handle this?",
512	        criteria={
513	            "returns": "Exchanges, wrong or damaged items",
514	            "shipping": "Delivery status, delays, lost packages",
515	            "billing": "Charges, invoices, payment problems",
516	        },
517	    ),
518	    "return_reason": Choice(
519	        instructions="If the customer wants to return something, why?",
520	        criteria={
521	            "wrong_size": "The item doesn't fit",
522	            "wrong_item": "A different product was delivered",
523	            "damaged": "The item arrived broken or faulty",
524	            "changed_mind": "The item is fine, the customer no longer wants it",
525	            "other": "A return reason that fits none of the above",
526	        },
527	    ),
528	    "shipping_issue": Choice(
529	        instructions="If this is a shipping problem, which kind is it?",
530	        criteria={
531	            "not_delivered": "The package never arrived",
532	            "delayed": "The package is late but still on its way",
533	            "wrong_address": "The package went to the wrong place",
534	            "damaged_in_transit": "The package arrived damaged",
535	            "other": "A shipping problem that fits none of the above",
536	        },
537	    ),
538	    "requested_resolution": Choice(
539	        instructions="What does the customer want to happen?",
540	        criteria={
541	            "exchange": "Swap the item for a different one",
542	            "refund": "Money back",
543	            "replacement": "The same item sent again",
544	            "information": "Just an answer, no action needed",
545	        },
546	    ),
547	    "tone": Choice(
548	        instructions="What is the customer's tone?",
549	        criteria={"calm": None, "frustrated": None, "angry": None},
550	    ),
551	}
552	
553	
554	def triage(ticket: str) -> None:
555	    with TypeSafeClient() as client:
556	        response = client.system_one(
557	            state=ticket,
558	            questions=TRIAGE_QUESTIONS,
559	        )
560	    answers = response.answers
561	
562	    department = answers["department"]
563	    if department.confidence < 0.3:
564	        # Not clear which team to send to. Let a person decide.
565	        send_to_manual_triage(ticket)
566	        return
567	
568	    if department.choice == "returns":
569	        # return_reason answer is only used here
570	        assign(ticket, team="returns", issue=answers["return_reason"].choice)
571	    elif department.choice == "shipping":
572	        # shipping_issue answer is only used here
573	        assign(ticket, team="shipping", issue=answers["shipping_issue"].choice)
574	    else:
575	        assign(ticket, team="billing")
576	
577	    # A second team with a real share of the probability gets a copy
578	    for team, probability in department.probabilities.items():
579	        if team != department.choice and probability > 0.25:
580	            notify(ticket, team=team)
581	
582	    resolution = answers["requested_resolution"]
583	    if resolution.confidence < 0.5:
584	        # The customer hasn't said what they want. Ask, don't guess.
585	        ask_customer_what_they_want(ticket)
586	    elif resolution.choice == "refund":
587	        flag_for_refund_approval(ticket)
588	
589	    if answers["tone"].choice == "angry":
590	        flag_for_senior_agent(ticket)
591	```
592	
593	For the ticket above, this assigns the ticket to the returns team with issue `wrong_size`, sends the billing team a copy because its 0.35 share is over the 0.25 threshold, and asks the customer what they want because the resolution confidence of 0.20 is under 0.5. The code does not use the `shipping_issue` answer.
594	
595	One request, five answers, and the routing logic is ordinary `if` statements. If you later need to know the customer's language, or which product the ticket is about, add another Choice question to `TRIAGE_QUESTIONS`; the request count stays at one.
596	
597	The [smart home assistant demo](/demos/smart-home) evaluates every user request against a long list of Choice questions in one call: the request category, the room, the device, and the action. Most of those questions are irrelevant to any one request and the code ignores them.
598	
599	## Structured instructions and criteria
600	
601	Start with a one-line description per option. When two options are similar and the model keeps confusing them, describe each one with an object instead of a string. Give it fields for what the option covers, what belongs to a neighboring option instead, and a few example inputs.
602	
603	The two answer options below, return\_policy and return\_status, are easy to confuse. A ticket about either one can mention returns and refunds, so each option says what it is not for.
604	
605	<TypesafeExample
606	  display="request"
607	  example={{
608	state: 'I sent the shoes back a week ago. When do I get my money?',
609	selectedModels: ['jev-latest'],
610	questions: {
611	  return_topic: {
612	    type: 'choice',
613	    instructions: {
614	      question: 'Which returns topic is the customer asking about?',
615	      focus: 'Classify the information the customer wants.',
616	    },
617	    criteria: {
618	      return_policy: {
619	        what: 'Whether and how an item can be returned',
620	        not_for: 'Progress of a return already sent',
621	        examples: [
622	          "Can I return shoes I've worn once?",
623	          'How long do I have to return an order?',
624	        ],
625	      },
626	      return_status: {
627	        what: 'Progress of a return already sent',
628	        not_for: 'Whether and how an item can be returned',
629	        examples: [
630	          'Has my return arrived yet?',
631	          'When will my refund be paid?',
632	        ],
633	      },
634	    },
635	  },
636	},
637	}}
638	/>
639	
640	The response is `return_status` at confidence 1.0:
641	
642	```json theme={null}
643	{
644	  "model": "jev-1.13.0",
645	  "answers": {
646	    "return_topic": {
647	      "type": "choice",
648	      "choice": "return_status",
649	      "confidence": 1.0,
650	      "probabilities": {
651	        "return_policy": 0.0,
652	        "return_status": 1.0
653	      }
654	    }
655	  },
656	  "usage": {
657	    "input_tokens": 407,
658	    "output_tokens": 32
659	  }
660	}
661	```
662	
663	The field names `question`, `focus`, `what`, `not_for`, and `examples` are not part of the API, and none are reserved. You choose them, the same way you choose option names. The model sees the names along with the values, so use short names that label what follows.
664

